import urllib.request
import json
import time

headers = {"User-Agent": "copilot-cli/1.0"}

versions = [f"0.9.{i}" for i in range(79, 101)]

for ver in versions:
    url = f"https://crates.io/api/v1/crates/rb-sys-build/{ver}/dependencies"
    req = urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(req) as response:
            data = json.loads(response.read().decode())
            for dep in data.get("dependencies", []):
                if dep.get("crate_id") == "bindgen":
                    print(f"Version: {ver}, bindgen requirement: {dep.get(\"req\")}")
        time.sleep(0.2)
    except Exception as e:
        print(f"Error for version {ver}: {e}")
'

